const e=n=>n.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),l=n=>{if(n.re)return new RegExp(n.re,"gi");const i=[n.en,...n.alt??[]].sort((c,a)=>a.length-c.length).map(e);return new RegExp(`(?<![A-Za-z])(?:${i.join("|")})(?![A-Za-z])`,"gi")};function u(n,i){if(!n)return[];const c=[];for(const h of i){const t=l(h);for(const g of n.matchAll(t))g.index!==void 0&&c.push({term:h,at:g.index,end:g.index+g[0].length})}const a=c.filter(h=>!c.some(t=>t!==h&&t.at<=h.at&&t.end>=h.end&&t.end-t.at>h.end-h.at)),r=new Set;return a.sort((h,t)=>h.at-t.at).filter(h=>r.has(h.term.en)?!1:(r.add(h.term.en),!0)).map(h=>h.term)}const p=[{en:"critical path",vi:"chuỗi hoạt động dài nhất xuyên dự án, quyết định ngày kết thúc sớm nhất — việc trên đó trượt một ngày là cả dự án trượt một ngày",trap:"Là đường DÀI NHẤT về thời lượng, không phải đường quan trọng nhất về nghiệp vụ hay tốn tiền nhất. Việc trên critical path có float bằng 0. Một dự án có thể có nhiều critical path song song, và critical path đổi chỗ mỗi khi lịch thay đổi — nên phải tính lại sau mỗi lần cập nhật, đừng tin bản vẽ tháng trước. Crashing hay fast-tracking chỉ có nghĩa khi áp lên critical path; rút một việc có float thì ngày kết thúc không nhích."},{en:"crashing",vi:"rút ngắn lịch bằng cách đổ thêm nguồn lực vào việc trên critical path — thêm người, thêm giờ, thuê ngoài",trap:'Cặp kinh điển crashing vs fast-tracking, phân biệt bằng "trả giá bằng gì": crashing TỐN THÊM TIỀN nhưng giữ nguyên trình tự việc nên không thêm rủi ro rework; fast-tracking KHÔNG tốn thêm tiền nhưng tăng rủi ro và rework. Đề nói "rút lịch mà không tăng chi phí" → fast-tracking; "rút lịch mà không tăng rủi ro" → crashing. Thêm người cũng không tự động nhanh hơn: chi phí giao tiếp và đào tạo có thể ăn hết phần rút được. Và khi đề chưa nói rõ mức ảnh hưởng thì việc đúng là đo tác động trước, chọn cách rút sau — nhảy thẳng vào crashing là lỗi kinh điển.'},{en:"fast-tracking",alt:["fast tracking","fast-track"],vi:"chạy song song các việc vốn phải làm lần lượt, để rút ngắn lịch mà không thêm chi phí",trap:"Ngược với crashing ở chỗ trả giá bằng gì: fast-tracking trả bằng RỦI RO và rework, vì việc sau bắt đầu khi việc trước chưa xong hẳn nên đầu vào còn có thể đổi; crashing trả bằng TIỀN. Chỉ song song được với phụ thuộc discretionary (do mình chọn cách làm), không phá được phụ thuộc mandatory kiểu bắt buộc kỹ thuật — móng chưa xong thì không dựng tường."},{en:"resource leveling",alt:["resource levelling"],vi:"sắp lại lịch cho nhu cầu nguồn lực không vượt mức thật sự có, thường bằng cách đẩy việc sang thời điểm khác",trap:'Resource leveling hay KÉO DÀI lịch và có thể đổi luôn critical path — nên nó gần như không bao giờ là đáp án cho câu "làm sao rút ngắn lịch" hay "làm sao dự báo ngày hoàn thành"; nó giải bài toán ràng buộc nguồn lực, không nói gì tới dự báo. Phân biệt với resource smoothing: smoothing chỉ dịch việc trong phạm vi float sẵn có nên KHÔNG đổi ngày kết thúc, leveling thì được phép đổi.'},{en:"milestone",alt:["milestones"],vi:"mốc đánh dấu một thời điểm hoặc sự kiện quan trọng trong lịch, thời lượng bằng 0 và không tiêu nguồn lực",trap:'Milestone không phải activity: không có duration, không có effort, không gán người làm. "Hoàn thành thiết kế" là milestone, "làm thiết kế" là activity. Một số milestone do hợp đồng hoặc bên ngoài áp đặt nên không thương lượng được, khác với ngày do đội tự đặt. Khác phase gate: milestone chỉ đánh dấu, không kèm quyền chặn giai đoạn sau.'},{en:"gantt chart",alt:["gantt charts","gantt"],vi:"biểu đồ thanh ngang theo trục thời gian, mỗi việc một thanh — nhìn ra ngay việc nào bắt đầu khi nào và kéo dài bao lâu",trap:'Gantt cho thấy THỜI GIAN nhưng che QUAN HỆ PHỤ THUỘC: nhìn Gantt bạn không biết vì sao việc B phải chờ việc A, và không thấy critical path — muốn thấy hai thứ đó thì cần network diagram. Vì vậy phương án "cập nhật Gantt và điều chỉnh timeline bằng tay" gần như luôn là bẫy êm: nó chỉ vẽ lại một kịch bản duy nhất do bạn phỏng đoán, không phân tích và không cho dải kết quả nào.'},{en:"network diagram",alt:["network diagrams"],vi:"sơ đồ nối các activity theo quan hệ phụ thuộc, dùng để tính critical path, float và ngày sớm/muộn của từng việc",trap:"Ngược với gantt chart: network diagram cho thấy PHỤ THUỘC và critical path nhưng không vẽ theo tỉ lệ thời gian, nên nhìn nó bạn không đọc ra lịch ngày tháng. Nó cũng không phân rã phạm vi — muốn có activity thì phải có work package từ WBS trước, thứ tự là WBS → activity list → network diagram → dựng lịch. Đề dùng sequence, dependency, predecessor là trỏ tới network diagram; dùng break down, organize into smaller components là trỏ tới WBS."},{en:"lag",vi:"khoảng chờ bắt buộc chèn giữa hai việc — bê tông đổ xong phải chờ khô mới làm bước sau",trap:"Lag làm lịch DÀI ra, lead làm lịch NGẮN lại. Lag không phải float: lag là độ chờ bạn cố ý đặt vào quan hệ giữa hai việc, float là dư thời gian tính ra được từ lịch. Cũng đừng lẫn lag với delay: lag là kế hoạch, delay là sự cố. Tinh chỉnh lead/lag là tối ưu lịch đã có, không giải được chuyện bản thân thời lượng các việc còn bất định."},{en:"lead",re:"lead\\s+time|lead\\s*(?:/|and|và)\\s*lag|lag\\s*(?:/|and|và)\\s*lead",vi:"cho việc sau bắt đầu sớm hơn, chồng lên phần cuối của việc trước, để rút lịch",trap:'Trong PMP, lead là độ chồng lấn giữa hai việc (bản chất là lag âm), không phải động từ "dẫn dắt" — trong đề chữ lead phần lớn là "lead the team", nên gặp chữ này phải xem nó đứng cạnh lag hay time mới là nghĩa lịch trình. Dùng lead tức là đang fast-track ở mức quan hệ giữa hai việc, nên nó cũng mang theo rủi ro rework.'},{en:"three-point estimate",alt:["three-point estimating","three point estimate"],vi:"ước lượng bằng ba số — lạc quan (O), khả năng nhất (M), bi quan (P) — thay vì một con số duy nhất, để tính cả phần bất định vào",trap:'Có HAI công thức và đề hay thử đúng chỗ này: triangular = (O + M + P)/3 coi ba số nặng như nhau, dùng khi dữ liệu quá khứ ít; beta/PERT = (O + 4M + P)/6 đánh trọng số gấp bốn cho M nên kết quả nghiêng về giá trị khả năng nhất và bị số bi quan cực đoan kéo lệch ít hơn. Đề không nói rõ thì PMI thường ngụ ý beta/PERT. Đây là công cụ LẬP KẾ HOẠCH cho việc chưa làm, nên nó không phải đáp án cho câu "dự án đã đi nửa đường, dự báo ngày hoàn thành" — lúc đó bạn đã có số thật, dùng EVM hoặc trend analysis.'},{en:"analogous estimating",alt:["analogous estimate"],vi:"lấy số liệu thật của một việc hoặc dự án tương đương đã làm rồi suy ra cho việc hiện tại",trap:'Nhanh và rẻ nhất nhưng cũng thô nhất, chỉ đáng tin khi hai việc thực sự giống nhau. Ba bậc cần phân biệt: analogous (so với việc tương đương, độ chính xác thấp, dùng khi thông tin còn ít), parametric (nhân theo đơn giá hoặc năng suất trên một đơn vị), bottom-up (cộng từ từng work package lên, chính xác nhất nhưng tốn công nhất). Đề tả "có dữ liệu lịch sử về công việc tương đương, cần số nhanh" là đang trỏ tới analogous — trong agile thì dữ liệu tương đương đó chính là velocity của các sprint trước.'},{en:"planning poker",vi:"cả nhóm ước lượng ẩn cùng lúc bằng thẻ, ai lệch xa nhất phải giải thích, rồi ước lượng lại tới khi hội tụ",trap:"Giá trị của planning poker KHÔNG nằm ở con số mà ở chỗ nó lôi ra các giả định đang giấu bên dưới: hai người chênh nhau 3 với 13 nghĩa là họ đang hiểu phạm vi khác nhau, và đó mới là thứ cần đưa ra ánh sáng. Vì vậy lấy trung bình cộng các phiếu là làm hỏng đúng phần giá trị của nó. Bỏ phiếu ẩn cũng để chống anchoring — người nói trước hoặc người có chức sẽ kéo cả nhóm theo mình. Wideband Delphi cùng cơ chế này."},{en:"work breakdown structure",alt:["WBS"],vi:"cây phân rã toàn bộ phạm vi thành các thành phần nhỏ dần, tới mức ước lượng và giao việc được",trap:"WBS phân rã SẢN PHẨM BÀN GIAO, không phải danh sách hành động theo thời gian và cũng không phải sơ đồ tổ chức. Mức thấp nhất gọi là work package — đơn vị đủ nhỏ để ước lượng chi phí và thời lượng một cách tin cậy. Quy tắc 100%: WBS chứa trọn phạm vi, cái gì không có trong WBS thì không thuộc dự án, đó là lý do WBS là vũ khí chống scope creep. WBS không có mũi tên phụ thuộc và không có ngày; phần đó là việc của network diagram."},{en:"decomposition",alt:["decompose","decomposing"],vi:"chẻ một hạng mục lớn thành các phần nhỏ hơn cho tới khi ước lượng và quản được — chính là kỹ thuật tạo ra WBS",trap:"Đề thường không gọi tên mà mô tả: break down, organize into smaller components, chia epic — đều là decomposition. Một hạng mục quá lớn còn giấu luôn cả phụ thuộc và rủi ro bên trong nó, nên chẻ nhỏ là cách chữa trực tiếp; nhưng chẻ quá sâu cũng là lỗi vì chi phí quản lý vượt lợi ích. Khác progressive elaboration: decomposition chẻ theo CẤU TRÚC (rộng thành hẹp), progressive elaboration làm rõ dần theo THỜI GIAN khi có thêm thông tin."},{en:"progressive elaboration",vi:"kế hoạch được chi tiết hoá dần theo thời gian, phần đã rõ thì làm kỹ, phần còn xa thì để ở mức thô",trap:'Progressive elaboration KHÔNG phải scope creep: phạm vi không phình ra, chỉ được làm rõ thêm bên trong phần đã thống nhất. Nó cũng không phải cái cớ cho "lập kế hoạch dở rồi sửa sau". Rolling wave planning là cách áp dụng cụ thể nguyên tắc này lên lịch.'},{en:"rolling wave planning",alt:["rolling wave"],vi:"lập kế hoạch chi tiết cho phần việc sắp tới, để phần xa ở mức thô, rồi chi tiết hoá dần khi tới gần",trap:'Đây là đáp án điển hình cho tình huống "yêu cầu phía sau còn mờ, không thể lập lịch chi tiết cho cả dự án ngay". Đừng nhầm với agile: rolling wave vẫn là predictive, vẫn có baseline và lịch tổng thể, chỉ khác là mức chi tiết không đều nhau. Cũng khác lead/lag optimization và backward pass — hai cái đó tinh chỉnh lịch đã có, còn rolling wave quyết định lập kế hoạch tới đâu thì dừng.'},{en:"scope creep",vi:"phạm vi phình ra từng chút một mà không qua change control, không ai duyệt và cũng không ai điều chỉnh lịch hay ngân sách theo",trap:"Cặp bắt buộc phân biệt là AI GÂY RA: scope creep đến từ BÊN NGOÀI đội — khách hàng, stakeholder xin thêm — và len vào được vì quy trình kiểm soát thay đổi lỏng; gold plating là CHÍNH ĐỘI tự thêm khi không ai yêu cầu. Cũng phải tách khỏi change hợp lệ: cùng là thêm việc, nhưng nếu đi qua change request, được duyệt và baseline được điều chỉnh thì đó là quản lý thay đổi bình thường, không phải creep. Thuốc chữa gốc là WBS và scope statement rõ, cộng một quy trình change control có người canh thật."},{en:"gold plating",alt:["gold-plating"],vi:"đội tự thêm tính năng hoặc mài giũa quá mức những thứ không ai yêu cầu, tưởng làm vậy là khách sẽ vui hơn",trap:"Khác scope creep ở NGUỒN GỐC: gold plating do nội bộ đội tự ý thêm, scope creep do yêu cầu từ ngoài len vào không qua kiểm soát. PMI luôn coi gold plating là sai dù thiện chí: nó tiêu ngân sách và thời gian cho giá trị không ai đặt hàng, đồng thời tăng rủi ro chất lượng. Trong agile, dấu hiệu là đội làm thêm việc ngoài sprint goal, hoặc cứ họp nội bộ mài sản phẩm theo ý mình thay vì đem cho khách xem sớm."},{en:"baseline",vi:"bản kế hoạch đã được duyệt và đóng băng (phạm vi, lịch, chi phí) làm mốc so sánh — thực tế lệch khỏi nó bao nhiêu thì gọi là variance",trap:"Baseline chỉ đổi được qua change request đã duyệt. Chỗ mất điểm phổ biến nhất: cập nhật tiến độ thực tế là sửa project management plan, KHÔNG phải sửa baseline — sửa baseline cho khớp thực tế là xoá mất thước đo. Khác EAC/forecast: baseline là cái ĐÃ HỨA lúc đầu, EAC là cái ĐANG DỰ BÁO sẽ thành; đặt hai số cạnh nhau mới ra bức tranh thật. Xin rebaseline khi chưa đo tác động cũng là bẫy quen: đo trước, rồi mới bàn chuyện đổi baseline với sponsor."},{en:"earned value",alt:["EVM","earned value management"],vi:"hệ đo gộp phạm vi, lịch và chi phí vào cùng một thước: so giá trị công việc đã thật sự hoàn thành (EV) với phần đã hoạch định (PV) và với tiền đã chi (AC)",trap:'Đọc dấu cho nhanh: SV = EV − PV, âm là chậm lịch; CV = EV − AC, âm là vượt chi. Bẫy lớn nhất của EVM là ĐƠN VỊ — cả SV và EAC đều tính bằng TIỀN, không phải bằng ngày; muốn nói chuyện thời gian thì phải sang earned schedule với SV(t) và EAC(t). Sức mạnh của EVM là gộp chi phí và tiến độ vào một thước duy nhất, nên trước lãnh đạo một câu "SPI 0,87 và CPI 0,94" nói được nhiều hơn hai mươi phút kể chuyện. Nhưng không phải con số EVM nào trong đề cũng để tính: rất nhiều câu chỉ dùng SPI/CPI như cách nói "dự án đang xấu đi", việc cần làm là tìm nguyên nhân chứ không phải bấm máy tính.'},{en:"CPI",alt:["cost performance index"],vi:"tỷ số hiệu quả chi phí, CPI = EV / AC — dưới 1 nghĩa là mỗi đồng bỏ ra thu về ít giá trị hơn kế hoạch, tức đang vượt chi",trap:"Nhớ một câu cho cả CPI và SPI: dưới 1 là xấu, trên 1 là tốt, đúng 1 là khớp kế hoạch. CPI nói về TIỀN, SPI nói về THỜI GIAN — tên hai index dễ lẫn nên cứ dịch ra: cost là tiền, schedule là lịch. Khác CV ở chỗ CPI là tỷ số nên nói được MỨC ĐỘ lệch và so sánh được giữa các dự án, còn CV chỉ cho hướng và độ lớn tuyệt đối. CPI 0,94 đọc là: đã tiêu một đồng mà chỉ tạo ra 0,94 đồng giá trị."},{en:"SPI",alt:["schedule performance index"],vi:"tỷ số hiệu quả tiến độ, SPI = EV / PV — dưới 1 nghĩa là làm được ít hơn phần đã hoạch định, tức đang chậm lịch",trap:'Dưới 1 là chậm, trên 1 là nhanh hơn kế hoạch. Hai bẫy: (1) SPI tính bằng TIỀN chứ không bằng thời gian, nên SPI 0,85 không dịch thẳng thành "chậm 15 ngày"; (2) SPI luôn bò về 1 khi dự án gần xong dù thực tế trễ, vì cuối cùng EV cũng bằng PV — chính điểm yếu này sinh ra earned schedule. Đề tả SPI tụt từ 1,05 xuống 0,85 là đang nói dự án chuyển từ vượt kế hoạch sang chậm, không phải mời bạn tính toán.'},{en:"EAC",alt:["estimate at completion"],vi:"estimate at completion — tổng chi phí dự báo cho tới lúc dự án xong, tính theo hiệu suất thực tế tới giờ chứ không theo lời hứa ban đầu",trap:'EAC là con số CHI PHÍ, không phải ngày hoàn thành — muốn dự báo NGÀY bằng EVM thì đại lượng đúng là EAC(t) của earned schedule; phương án nào nói "tính EAC để ra ngày hoàn thành" là đang dùng thuật ngữ lỏng. Phân biệt với baseline/BAC: BAC là ngân sách đã duyệt lúc đầu (cái đã hứa), EAC là dự báo hiện tại (cái sẽ thành), và VAC = BAC − EAC cho biết cuối cùng thừa hay thiếu tiền. Công thức hay dùng EAC = BAC / CPI ngầm giả định phần việc còn lại chạy với hiệu suất y như phần đã làm — giả định đó phải hợp lý mới được dùng.'},{en:"earned schedule",vi:"phần mở rộng của EVM đo tiến độ bằng ĐƠN VỊ THỜI GIAN thật, cho ra SV(t) và EAC(t) thay vì những con số tiền",trap:'Sinh ra chính vì điểm yếu của SV và SPI: chúng tính bằng tiền, và mất khả năng phân biệt khi dự án gần xong (SPI luôn tiến về 1). Nếu đề hỏi dự báo NGÀY hoàn thành mà phương án nói "dùng SV để đo mức lệch thời gian" hoặc "tính EAC để ra ngày", hãy nhận ra đó là cách dùng từ lỏng — đại lượng chuẩn là SV(t) và EAC(t).'},{en:"trend analysis",vi:"xem số liệu hiệu suất theo chuỗi thời gian để thấy xu hướng đang tốt lên hay xấu đi, rồi ngoại suy tới tương lai",trap:"Trend analysis cho CHIỀU đi của dự án chứ không cho một con số dự báo chắc như EVM, và cũng không cho xác suất như Monte Carlo — đây là distractor rất mạnh trong các câu hỏi dự báo ngày hoàn thành. Thứ tự chọn: cần xác suất và dải kết quả → Monte Carlo; cần một con số từ dữ liệu hiệu suất đã có → EVM; chỉ cần biết đang xấu đi hay tốt lên → trend analysis. Nó còn cần đủ dữ liệu quá khứ, nên đầu dự án thì vô dụng."},{en:"sensitivity analysis",vi:"xếp hạng xem biến nào ảnh hưởng mạnh nhất tới kết quả dự án, bằng cách lần lượt thay đổi từng biến và giữ các biến còn lại cố định",trap:'Cho biết biến NÀO quan trọng nhất, không cho XÁC SUẤT hoàn thành đúng hạn hay đúng ngân sách — muốn xác suất thì Monte Carlo. Hai công cụ này hay đứng cạnh nhau trong cùng một câu để thử xem bạn có đọc kỹ đề: thấy "which variables most significantly impact" là sensitivity analysis, thấy "probability" hoặc "range of outcomes" là Monte Carlo. Biểu diễn quen thuộc của nó là tornado diagram.'},{en:"phase gate",alt:["phase gates","phase-gate"],vi:"điểm cuối một giai đoạn, nơi bên có thẩm quyền ra quyết định đi tiếp / dừng / làm lại trước khi giai đoạn sau được phép bắt đầu",trap:"Bản chất phase gate là QUYẾT ĐỊNH go/no-go của người có quyền, không phải một buổi họp báo cáo cho đủ thủ tục. Vì thế bàn giao xong mà quyết định đi tiếp chưa có thì bạn CHƯA được khởi động giai đoạn sau, dù đã thông báo đủ mọi stakeholder — thông báo không thay được phê duyệt. Khác milestone: milestone chỉ đánh dấu một mốc, phase gate có quyền chặn. Khác retrospective: gate soi tính khả thi và giá trị kinh doanh của việc tiếp tục, retro soi cách đội làm việc."}],m=[{en:"risk register",vi:"sổ ghi từng rủi ro đã nhận diện, kèm phân tích, chiến lược ứng phó đã thống nhất, người chịu trách nhiệm và ngưỡng kích hoạt — thứ bạn mở ra tra trước khi tự nghĩ cách ứng biến",trap:'Ranh giới với issue log: risk register chứa chuyện CHƯA xảy ra, issue log chứa chuyện ĐÃ xảy ra. Khi một rủi ro thành hiện thực thì nó chuyển sổ — sang issue log — nhưng phản ứng vẫn lấy từ register vì phương án ứng phó nằm ở đó. Đừng lẫn với risk management plan: plan nói bạn quản lý rủi ro theo quy trình nào, ai làm gì, ngưỡng bao nhiêu; register là danh sách rủi ro cụ thể. Trong bank này, đề nào nói rủi ro "đã được nhận diện trước đó" mà hỏi bước đầu tiên thì đáp án gần như luôn là mở register và thi hành phản ứng đã hoạch định, không phải họp nhóm nghĩ giải pháp mới.'},{en:"issue log",vi:"sổ ghi những việc đã xảy ra và đang cản dự án, kèm tác động, mức khẩn, chủ sở hữu và hạn xử lý",trap:'Cặp kinh điển với risk register: rủi ro là việc chưa xảy ra, issue là việc đã xảy ra. Tín hiệu trong đề là thì của động từ: "has encountered", "has indicated", "is currently delaying" đều là issue; "could potentially derail", "may not meet" vẫn là risk. Bẫy thứ hai là bạn thấy "chỉ ghi vào sổ" thì nghĩ đáp án đó nhẹ tay quá nên loại — nhưng ghi nhận không phải thủ tục hình thức, nó ép bạn chốt ba dữ kiện (vấn đề chính xác là gì, tác động tới đâu, khẩn tới mức nào) mà thiếu chúng thì mọi hành động sau đều là đoán.'},{en:"Monte Carlo simulation",alt:["Monte Carlo"],vi:'chạy hàng nghìn kịch bản với mỗi biến dao động theo phân phối của nó, trả về phân bố xác suất của ngày hoàn thành hoặc tổng chi phí, kiểu "80% khả năng xong trước ngày X"',trap:'Monte Carlo thuộc quantitative risk analysis — nó ra số, không ra hạng. Khác sensitivity analysis: sensitivity chỉ xếp hạng biến nào chi phối mạnh nhất mà không cho xác suất nào, nên đề chỉ hỏi "biến nào ảnh hưởng nhiều nhất" thì chọn sensitivity. Ba từ khoá gọi Monte Carlo: bất định, nhiều biến cùng tác động, và cần một dải kết quả kèm xác suất. Bẫy ngược quan trọng: nếu đề đã nói nhóm đang dùng EVM và chỉ hỏi một con số dự báo thì đáp án là ngoại suy từ chỉ số đo được (EAC/SPI), không phải Monte Carlo — bank có đúng một cặp câu đối nhau ở chỗ này, một câu Monte Carlo là đáp án và một câu nó bị loại.'},{en:"quantitative risk analysis",vi:'định lượng rủi ro bằng số — xác suất, tiền, ngày — để trả lời được câu hỏi kiểu "khả năng xong trước ngày X là bao nhiêu phần trăm" hoặc "rủi ro này đáng giá bao nhiêu tiền"',trap:'Đối lập với qualitative risk analysis: qualitative xếp HẠNG (cao/trung/thấp, qua probability-impact matrix) để sàng lọc xem rủi ro nào đáng phân tích sâu, và nó làm TRƯỚC; quantitative mới quy ra SỐ, và chỉ làm cho phần đã sàng. Thuộc nhóm định lượng: Monte Carlo simulation, sensitivity analysis, decision tree, EMV. Thuộc nhóm định tính: probability-impact matrix, cause-and-effect diagram, và cả risk breakdown structure — RBS phân loại rủi ro chứ không tính ra xác suất nào. Cụm "qualitative risk analysis" không xuất hiện thành chữ trong bank, nhưng đề vẫn dùng đúng lằn ranh này để loại phương án, nên nhớ ranh giới quan trọng hơn nhớ tên.'},{en:"risk appetite",vi:"mức bất định mà tổ chức chủ động chấp nhận để đổi lấy lợi ích — nó là thứ định hướng bạn được phép chọn chiến lược ứng phó nào",trap:'Ba từ dễ lẫn, khác nhau ở độ cụ thể. Risk appetite là thiên hướng ở tầng tổ chức, mang tính định tính ("chúng ta sẵn sàng mạo hiểm để ra thị trường sớm"). Risk tolerance là mức chịu được, đã có biên độ ("chậm tối đa hai tuần"). Risk threshold là con số ghi trong risk management plan mà vượt qua là phải hành động hoặc escalate. Hai từ sau không xuất hiện trong bank này nên đừng đi tìm chúng trong phương án; risk appetite thì có, và nó xuất hiện đúng theo nghĩa "phản ứng phải khớp với chiến lược và chính sách đã chốt trước", tức là một lý do nữa để tra tài liệu đã lập thay vì ứng biến.'},{en:"risk breakdown structure",alt:["RBS"],vi:"cây phân loại rủi ro theo nguồn gốc — kỹ thuật, môi trường, pháp lý, nhà thầu — để nhận diện cho đủ và không bỏ sót cả một nhóm rủi ro",trap:'Cảnh báo viết tắt trước: ngoài PMBOK, RBS còn là resource breakdown structure (cây phân rã nguồn lực theo loại). Trong bank này RBS luôn là risk breakdown structure — resource breakdown structure không xuất hiện câu nào — nhưng khi đi thi thì đọc ngữ cảnh: đang nói về rủi ro hay về nguồn lực. Bẫy thứ hai: RBS là công cụ TỔ CHỨC rủi ro, nó không cho ra xác suất nào, nên đề đòi likelihood hay probability of finishing thì RBS là distractor mạnh mà sai. Bẫy thứ ba là hai cách làm hỏng RBS mà đề hỏi thẳng: chỉ đưa rủi ro ưu tiên cao vào (lọc trước khi nhận diện là tự tạo điểm mù) và dựng nhiều tầng subcategory để "bắt hết mọi rủi ro" (làm RBS phình ra tới mức không ai dùng nổi).'},{en:"contingency reserve",vi:"tiền hoặc thời gian để dành sẵn cho những rủi ro đã nhận diện trong risk register, nằm trong cost baseline và PM được tự quyết dùng khi rủi ro đó nổ ra",trap:'Cặp bắt buộc phân biệt với management reserve. Contingency reserve: known unknowns — rủi ro đã biết, đã ước lượng, nằm TRONG cost baseline, PM tự dùng. Management reserve: unknown unknowns — thứ không lường trước, nằm NGOÀI cost baseline (trong project budget), PM muốn dùng phải xin sponsor hoặc cấp trên và thường kéo theo change request. Nhớ gọn: known thì PM tự dùng, unknown thì phải xin. Lưu ý management reserve không xuất hiện trong bank này nên nó sẽ không thành đáp án, nhưng ranh giới vẫn phải nắm. Bẫy riêng của contingency reserve: nó là chuẩn bị để PHẢN ỨNG, không phải biện pháp phòng ngừa — đề hỏi "proactive measure could the project manager have taken" thì lập reserve trượt, vì tiền để dành không làm rủi ro bớt xảy ra.'},{en:"contingency plan",vi:"phương án dự phòng soạn sẵn cho một rủi ro đã nhận diện, chỉ kích hoạt khi rủi ro đó thật sự xảy ra",trap:'Khác workaround ở chỗ chuẩn bị trước hay ứng biến tại chỗ: contingency plan cho rủi ro đã nhận diện và đã có kế hoạch, workaround cho việc không ai lường trước. (PMI còn có fallback plan — thứ dùng khi contingency plan chạy mà không đủ.) Nhưng cái đáng cảnh báo hơn với bank này: contingency plan xuất hiện bốn lần và cả bốn lần đều là phương án SAI. Nó là mẫu distractor "để dành cho sau" — được thả vào những câu mà vấn đề đang xảy ra ngay lúc này và bạn còn chưa hiểu nguyên nhân. Lập kế hoạch dự phòng cho một chuyện bạn chưa hiểu là lập kế hoạch cho phỏng đoán; khi đề hỏi bước đầu tiên với một xung đột đang có thật, hãy đi hiểu trước.'},{en:"workaround",alt:["workarounds"],vi:"cách vá tạm nghĩ ra ngay tại chỗ để đi tiếp, dùng cho việc đã xảy ra mà không ai lường trước nên không có phương án dự phòng nào sẵn",trap:'Ngược với contingency plan: một cái ứng biến, một cái đã soạn trước. Dấu hiệu nhận ra workaround trong phương án: nó giúp kịp hạn ngay mà không sửa gì ở nguyên nhân — "assign a team to develop a workaround", "dồn việc cho người giỏi để giữ tiến độ". Trong bank này workaround gần như luôn sai, vì hai lý do khác nhau: đề hỏi "what would have prevented this" thì vá tạm không trả lời câu phòng ngừa; và workaround cho một chính sách của bộ phận khác (bảo mật, IT) là thứ bạn không có quyền tự phán, rủi ro tuân thủ lớn hơn vài ngày trễ. Cũng lưu ý workaround thường tạo ra rủi ro mới, kiểu key-person risk khi bạn dồn hết việc quan trọng vào vài người.'},{en:"quality assurance",alt:["QA"],vi:"soi và cải tiến QUY TRÌNH làm ra sản phẩm để lỗi đừng sinh ra — quality audit, rà soát chuẩn, sửa quy trình test đều thuộc nhóm này",trap:'Đây là bẫy kinh điển nhất của PMP, và ranh giới rất gọn: QA soi QUY TRÌNH và PHÒNG NGỪA, QC soi SẢN PHẨM và PHÁT HIỆN. Dấu hiệu QA trong đề: "update quality assurance procedures", "quality audit", "refine the testing process", "training on standards" — tất cả tác động lên cách làm. Bẫy thời điểm mới là chỗ mất điểm thật: sửa quy trình QA là phòng cho LẦN SAU, nên khi lỗi đã xảy ra rồi và stakeholder đang hỏi có nên đi tiếp không, "cập nhật quy trình QA" không trả lời câu đang được hỏi. Chi tiết cuối: đề hay nhắc "the quality assurance team/lead" như một nhóm người — đó là nhân sự trong tình huống, đừng vì thấy chữ QA mà kết luận câu hỏi đang về hoạt động QA.'},{en:"quality control",vi:"kiểm chính SẢN PHẨM đã làm ra xem có đạt chuẩn không — inspection, test, checkpoint, đo deliverable so với tiêu chí nghiệm thu",trap:'Nửa còn lại của cặp QA/QC: QC nhìn đầu ra và PHÁT HIỆN lỗi, QA nhìn quy trình và PHÒNG NGỪA lỗi. Dấu hiệu QC: "inspection", "quality control checkpoint", "continuously monitor the product against regulatory standards", "test kết quả trước khi giao". Bẫy thời điểm đối xứng với QA: thêm quality control check là biện pháp cho những gì SẮP làm, nên nó không xử lý được những hoạt động đang có dấu hiệu lệch chuẩn ngay lúc này — đề tả tình trạng hiện tại thì phải tìm nguyên nhân rồi corrective action. Một chỗ người học Việt hay hiểu lệch vì dịch sát: "control" ở đây là ĐO rồi ĐỐI CHIẾU, không phải "kiểm soát" theo nghĩa ra lệnh hay siết chặt. QC chỉ ra defect; việc sửa defect là defect repair, không phải bản thân QC.'},{en:"corrective action",alt:["corrective actions"],vi:"việc làm để kéo hiệu suất đang lệch trở lại khớp với kế hoạch — có chủ, có hạn, có nguồn lực, và đưa vào project plan để theo dõi như mọi công việc khác",trap:'Bộ ba hay bị lẫn, phân biệt bằng đối tượng và thời điểm: corrective action sửa cái ĐÃ lệch để về đúng quỹ đạo; preventive action chặn cái CHƯA xảy ra nhưng đã thấy nguy cơ; defect repair sửa một SẢN PHẨM lỗi cụ thể. Dấu hiệu corrective trong đề: đã có sai lệch, non-conformance, hoặc audit findings nằm trên bàn. Đừng loại corrective action chỉ vì nó "nghe bị động" — bank có một chùm ba câu liền về quality audit mà đáp án cả ba đều là corrective action, chỉ khác thời điểm trong chu trình. Thêm hai chi tiết ăn điểm: corrective action chỉ có giá trị khi được đưa vào kế hoạch để có chủ và có hạn, và nếu nó ảnh hưởng baseline thì phải đi qua change control.'},{en:"preventive action",vi:"việc làm để chặn một sai lệch chưa xảy ra nhưng đã thấy nguy cơ — mục tiêu là hạ xác suất, không phải chữa hậu quả",trap:'Ngược chiều corrective action: corrective chờ lệch rồi mới kéo về, preventive chặn từ trước. Trong bank, tín hiệu là mấy tính từ trong câu hỏi và chúng hoạt động như bộ lọc cứng: "proactive", "preventive", "long-term", hoặc dạng câu "what would have prevented this from happening" — gặp chúng thì loại thẳng mọi phương án chỉ kích hoạt sau khi sự cố đã xảy ra, dù phương án đó nghe rất hữu ích. Bẫy ngược cũng có thật: khi đề đã kể một sai lệch đang diễn ra thì preventive action là distractor lệch thì. Đừng lẫn với quality assurance — QA cũng phòng ngừa nhưng ở tầng quy trình, còn preventive action là một hành động cụ thể nhắm vào một nguy cơ cụ thể.'},{en:"defect repair",vi:"sửa hoặc thay một sản phẩm, cấu phần đã bị phát hiện lỗi để nó đạt yêu cầu — phạm vi hẹp, nhắm đúng vào deliverable đó",trap:"Chỗ thứ ba của bộ ba: corrective action nhắm vào hiệu suất và cách làm đang lệch, preventive action nhắm vào nguy cơ chưa xảy ra, defect repair nhắm vào một sản phẩm lỗi đã có trong tay. Dấu hiệu: đề nói tới một deliverable hay component cụ thể không đạt spec. Hai điều đi kèm hay bị hỏi: sửa xong phải kiểm lại, và bước xác nhận đó thuộc quality control; defect repair gần như luôn sinh ra rework, nhưng hai từ không đồng nghĩa — defect repair là việc sửa sản phẩm, rework là phần công phải làm lại."},{en:"rework",vi:"phần việc phải làm lại vì kết quả lần đầu không đạt yêu cầu, nên thời gian và tiền của lần đầu coi như mất — đây là chi phí của chất lượng kém",trap:'Rework là HỆ QUẢ, không phải một hành động bạn chọn, nên nó hầu như không bao giờ là đáp án — nó là thứ để bạn nhận ra tình huống. Dấu vân tay trong đề: chi phí và lịch cùng xấu đi một lúc, vì làm nhầm rồi làm lại thì mất cả hai; và khi thấy dấu hiệu đó, nguyên nhân thường nằm ở khâu hiểu yêu cầu chứ không phải khâu thực thi. Hai nguồn sinh rework mà đề hay cài: fast-tracking (việc sau bắt đầu khi việc trước chưa chốt) và bắt đầu làm trên đặc tả còn mơ hồ trong lúc chờ làm rõ. Đừng dịch rework thành "sửa lỗi" chung chung, vì như vậy nó lẫn với defect repair.'},{en:"root cause analysis",alt:["RCA"],vi:"truy từ triệu chứng xuống nguyên nhân thật sự sinh ra nó trước khi chọn giải pháp — 5 whys và cause-and-effect diagram (Ishikawa) là hai công cụ hay dùng",trap:'Đây là mẫu đáp án phổ biến nhất của bộ đề: khi đề tả một TRIỆU CHỨNG mà không nói nguyên nhân, đáp án gần như luôn là bước tìm hiểu (root cause analysis, gather information, meet to understand), còn các phương án hành động cụ thể kia đều đang âm thầm giả định sẵn một nguyên nhân rồi nhảy vào chữa. Bẫy ngược thì tinh hơn: khi RCA đã được đề xuất hoặc findings đã có sẵn trên bàn, câu hỏi không còn là "có nên làm RCA" mà là bước tiếp theo — chọn RCA thêm lần nữa là chậm một nhịp. Trong bối cảnh agile, đề còn cài lớp thứ hai lên chính chữ RCA: ai quyết định làm nó — thu thập ý kiến nhóm và cùng nhóm quyết định là hai phương án khác nhau.'},{en:"value engineering",vi:"tối ưu tỷ lệ chức năng trên chi phí: hạ chi phí mà giữ nguyên công năng cần có, bằng cách hỏi mỗi thành phần phục vụ chức năng gì và có cách nào rẻ hơn đạt đúng chức năng đó",trap:'Phân biệt với cost cutting: value engineering giữ công năng rồi mới tìm cách rẻ hơn, cost cutting chỉ nhìn con số nên sẵn sàng cắt cả chức năng. Vì vậy một đề xuất "giảm hiệu năng để tiết kiệm nhiều tiền" không tự động đạt hay không đạt — phải xét phần hiệu năng bị giảm có nằm trong chức năng thiết yếu hay không, và đó chính là đáp án chứ không phải duyệt ngay hay bác ngay. Trình tự cũng bị hỏi: bước đầu của VE luôn là function analysis, vì chưa biết chức năng nào critical thì mọi khoản cắt đều là cắt mù. Và VE không phải công cụ rủi ro hay công cụ đo — Monte Carlo mô phỏng bất định, earned value đo mức lệch, cả hai đều không đề xuất cách hạ chi phí. Đề thường viết đủ "Value Engineering (VE)" ở lần đầu rồi dùng VE ở các câu sau.'}],s=[{en:"sprint",alt:["sprints"],vi:'một lượt làm việc có độ dài cố định (thường 1–4 tuần), cuối lượt phải có một increment dùng được, chứ không phải một đợt "tăng ca cho kịp"',trap:"Độ dài sprint là cố định: không kéo dài thêm vài ngày để nhét cho xong việc, việc chưa xong thì quay về product backlog. Phạm vi đã chốt trong sprint thì không ai nhét thêm việc vào giữa sprint, kể cả product owner; muốn đổi hướng thì đợi sprint sau. Chỉ product owner có quyền hủy một sprint."},{en:"product owner",alt:["PO","product owners"],vi:"người quyết định LÀM GÌ và theo thứ tự nào: sở hữu product backlog, xếp ưu tiên, và chịu trách nhiệm về giá trị sản phẩm giao ra",trap:'Ba vai đề PMP hay hỏi lẫn: product owner quyết NỘI DUNG và thứ tự ưu tiên; scrum master bảo vệ CÁCH LÀM và gỡ trở ngại; project manager chịu trách nhiệm KẾT QUẢ tổng thể và quan hệ với bên ngoài đội. Câu hỏi kiểu "ai chốt một tính năng thế nào là đủ" hay "ai quyết cái nào làm trước" thì đáp án là product owner — không phải scrum master, không phải nhóm dev, không phải sponsor.'},{en:"scrum",vi:"khung làm việc agile chạy theo sprint, với ba vai (product owner, scrum master, developers) và bộ sự kiện cố định",trap:'Scrum là một framework cụ thể, không đồng nghĩa với "agile" — kanban cũng là agile mà không có sprint. Khi đề nói nhóm đang chạy Scrum, bạn bị ràng buộc vào các vai của nó, nên phương án nào phá ranh giới vai (project manager tự xếp ưu tiên backlog, scrum master phân việc cho từng người) là sai ngay.'},{en:"scrum master",alt:["scrum masters"],vi:"người bảo vệ cách làm và gỡ trở ngại cho nhóm: kèm nhóm dùng Scrum cho đúng, giữ các sự kiện đúng mục đích, che nhóm khỏi nhiễu từ bên ngoài",trap:'Bẫy hay gặp nhất: scrum master KHÔNG phải người ưu tiên backlog — đó là product owner. Cũng không phân việc cho từng thành viên (nhóm tự nhận việc), không phải quản lý cấp trên của nhóm, không phải người duyệt kết quả. Đây là vai servant leadership: sức mạnh nằm ở chỗ tháo rào chắn, không ở chỗ ra lệnh. Thấy phương án bắt đầu bằng "scrum master quyết định..." thì phải nghi.'},{en:"product backlog",alt:["product backlogs"],vi:"danh sách duy nhất, xếp theo thứ tự ưu tiên, của mọi thứ có thể làm cho sản phẩm — sống suốt đời sản phẩm và được tinh chỉnh liên tục",trap:'Khác sprint backlog ở cả chủ sở hữu và phạm vi: product backlog do product owner sở hữu, phủ toàn bộ sản phẩm và không bao giờ "xong"; sprint backlog do nhóm developers sở hữu và chỉ chứa phần đã chọn cho sprint này. Việc phát sinh giữa sprint đi vào product backlog để xếp ưu tiên, không nhét thẳng vào sprint đang chạy.'},{en:"sprint backlog",vi:"phần việc nhóm đã chọn từ product backlog cho sprint này, kèm mục tiêu sprint và kế hoạch làm",trap:"Chủ sở hữu là nhóm developers, không phải product owner — nên trong sprint chỉ nhóm được sửa nó, và nhóm được tự điều chỉnh kế hoạch mà không xin phép. Đây là điểm phân biệt với product backlog (product owner sở hữu, phạm vi toàn sản phẩm, không giới hạn thời gian)."},{en:"sprint review",alt:["sprint reviews"],vi:"buổi cuối sprint để nhóm trình increment cho stakeholder và lấy phản hồi về SẢN PHẨM, rồi điều chỉnh product backlog theo phản hồi đó",trap:"Bẫy kinh điển của đề PMP: sprint review soi SẢN PHẨM và có stakeholder tham dự; retrospective soi CÁCH LÀM VIỆC và chỉ nội bộ đội. Đề nói muốn lấy phản hồi của khách về tính năng vừa làm thì chọn sprint review; nói nhóm muốn cải thiện cách phối hợp thì chọn retrospective. Sprint review cũng không phải buổi phê duyệt hình thức hay báo cáo tiến độ một chiều — nó là buổi làm việc để chỉnh hướng sản phẩm."},{en:"retrospective",alt:["retrospectives"],vi:"buổi cuối sprint để nội bộ đội soi lại CÁCH mình đang làm việc và chốt vài cải tiến cụ thể cho sprint sau",trap:"Đừng lẫn với sprint review (soi sản phẩm, có stakeholder). Retrospective là chỗ an toàn của đội: kéo stakeholder hay quản lý cấp trên vào ngồi nghe là phá đúng cái làm nó hữu ích. Đây cũng là phiên bản adaptive của lessons learned, nhưng làm mỗi sprint thay vì để tới cuối dự án. Kết quả phải là hành động cải tiến có người nhận, không phải một danh sách phàn nàn."},{en:"daily scrum",vi:"buổi 15 phút mỗi ngày để nhóm developers tự đồng bộ kế hoạch cho 24 giờ tới và phát lộ trở ngại",trap:"Không phải buổi báo cáo tiến độ lên scrum master hay project manager — nhóm nói với nhau, không nói với cấp trên. Cũng không phải chỗ giải quyết vấn đề: phát lộ trở ngại ở đây rồi hẹn xử lý riêng sau buổi, nếu đào sâu ngay thì 15 phút thành một tiếng và mất luôn tác dụng."},{en:"daily standup",alt:["daily stand-up","standup","standups","stand-up","stand-ups"],vi:"tên gọi chung của buổi đồng bộ ngắn hằng ngày trong nhóm agile — đứng mà họp chính là để giữ nó ngắn",trap:'Trong Scrum tên chính thức là daily scrum; standup là cách gọi phổ biến và dùng được cho cả nhóm không chạy Scrum. Bẫy hay gặp là "nghe thấy một người báo tắc suốt mấy ngày ở standup thì làm gì": đúng là ghi nhận rồi xử lý riêng ngay sau buổi, sai là đào sâu tại chỗ hoặc lập tức leo lên quản lý.'},{en:"definition of done",alt:["DoD"],vi:"bộ tiêu chí chung cả đội thống nhất, hạng mục nào chưa đạt thì chưa được tính là xong, dù code đã chạy",trap:'Phân biệt với definition of ready — cùng dạng danh sách điều kiện nhưng ở hai đầu ngược nhau của luồng việc: ready là đủ rõ để ĐƯA VÀO sprint, done là đủ chuẩn để RA KHỎI sprint. Cũng khác acceptance criteria: definition of done áp cho MỌI hạng mục, acceptance criteria viết riêng cho từng user story. Theo definition of done thì không có "xong 90%": hoặc xong hoặc chưa.'},{en:"user story",alt:["user stories"],vi:'một nhu cầu viết từ góc nhìn người dùng ("là ..., tôi muốn ..., để ..."), nhỏ đủ để làm xong trong một sprint và là cái cớ để đối thoại chứ không phải bản đặc tả',trap:'User story không phải requirement viết lại cho đẹp: giá trị nằm ở phần "để làm gì", nên phương án bỏ lý do đi cho gọn là sai hướng. Điều kiện chấp nhận riêng của nó là acceptance criteria; mức xong chung của cả đội là definition of done. Story quá lớn không vừa một sprint thì tách nhỏ, chứ không kéo dài sprint.'},{en:"story point",alt:["story points"],vi:"đơn vị ước lượng tương đối cho một hạng mục, gộp cả khối lượng, độ phức tạp và độ bất định — cố ý không quy ra giờ",trap:'Đây là thước đo NỘI BỘ của một đội cụ thể: 5 điểm của đội A không bằng 5 điểm của đội B. Mọi phương án đem story point so sánh giữa các đội, hay dùng làm KPI cho cá nhân, đều sai. Quy đổi cứng kiểu "1 point = 8 giờ" cũng làm mất đúng cái lý do người ta chọn điểm thay vì giờ.'},{en:"velocity",vi:"số story point một đội hoàn thành được mỗi sprint, lấy trung bình vài sprint để dự báo đội đó làm được bao nhiêu trong các sprint tới",trap:"Velocity là công cụ DỰ BÁO của chính đội đó, không phải thước đo năng suất để so đội này với đội khác hay để giao chỉ tiêu — biến nó thành KPI thì đội sẽ thổi điểm lên và con số mất giá trị dự báo. Đội mới hoặc vừa thay người thì velocity chưa nói được gì cho tới khi ổn định qua vài sprint."},{en:"burndown",alt:["burn-down"],vi:"đồ thị vẽ khối lượng việc CÒN LẠI giảm dần theo thời gian, để thấy nhóm có đang trên đường về đích hay không",trap:"Khác burnup: burndown chỉ vẽ phần còn lại, nên khi phạm vi bị thêm vào, đường đi ngang hoặc dội lên mà bạn không phân biệt được là do nhóm làm chậm hay do bị nhét thêm việc. Muốn nhìn ra scope creep thì dùng burnup."},{en:"burnup",alt:["burn-up"],vi:"đồ thị vẽ hai đường — việc đã xong và tổng phạm vi — nên nhìn được cả tiến độ lẫn phần phạm vi bị đội lên",trap:'Điểm mạnh so với burndown nằm ở đường tổng phạm vi: khi có việc nhét thêm, đường tổng dâng lên và scope creep hiện ra ngay trên đồ thị. Burndown chỉ cho bạn thấy "sao mãi không giảm" mà không nói được vì sao, nên khi đề hỏi biểu đồ nào cho thấy phạm vi bị thay đổi thì chọn burnup.'},{en:"kanban",vi:"cách làm việc theo luồng liên tục: hiện mọi việc lên bảng theo cột trạng thái, giới hạn số việc đang làm cùng lúc (WIP limit), và kéo việc mới vào khi có chỗ trống",trap:"Kanban là agile nhưng không có sprint, không bắt buộc ước lượng, và không có các vai của Scrum — nên khi đề mô tả nhóm cần giao liên tục, ưu tiên thay đổi thường xuyên, không muốn đóng khung theo chu kỳ thì kanban hợp hơn Scrum. Cột bị nghẽn trên bảng là tín hiệu để hạ WIP limit và dồn sức thông chỗ nghẽn, không phải để thêm người hay mở thêm việc mới."},{en:"minimum viable product",alt:["MVP"],vi:"phiên bản nhỏ nhất nhưng vẫn dùng được, tung ra sớm để học từ phản hồi thật thay vì đoán tiếp trên giấy",trap:'Chữ "viable" là phần hay bị bỏ qua: MVP phải dùng được và mang lại giá trị thật, không phải bản nửa vời hay prototype dùng xong bỏ. Trong bank này có một mẫu lặp lại: khi đề mô tả bất định, yêu cầu mơ hồ, hoặc chưa rõ stakeholder sẽ dùng sản phẩm thế nào, phương án tạo ra thứ nhìn thấy được sớm (MVP, prototype, spike, demo) gần như luôn thắng phương án "phân tích thêm rồi mới quyết".'},{en:"increment",alt:["increments"],vi:"phần sản phẩm cộng thêm sau một lượt làm, đã đạt definition of done và ghép được với các phần trước thành một tổng thể dùng được",trap:"Increment là KẾT QUẢ (một miếng sản phẩm), iteration là LƯỢT LÀM (một khoảng thời gian) — một iteration tạo ra một increment, đừng đổi chỗ hai từ. Increment chưa đạt definition of done thì không tính là increment. Từ này cũng nằm bên trong incremental, nên đọc kỹ đề đang nói về thứ giao ra hay về cách tiếp cận."},{en:"incremental",alt:["incrementally"],vi:"cách tiếp cận giao sản phẩm theo từng miếng dùng được, mỗi miếng cộng thêm vào phần đã giao cho tới khi đủ",trap:'Incremental (chia nhỏ để giao dần) khác iterative (làm lại nhiều lượt để làm cho đúng): giao lần lượt 3 tính năng hoàn chỉnh là incremental; dựng bản thô rồi tinh dần cùng một thứ là iterative. Thực tế agile dùng cả hai cùng lúc, nhưng đề PMP hay tách riêng để thử bạn, nên đọc xem đề đang nhấn vào "giao dần" hay "chỉnh dần".'},{en:"iteration",alt:["iterations"],vi:"một lượt làm có thời hạn cố định, hết lượt thì xem lại kết quả và điều chỉnh trước khi vào lượt sau",trap:"Iteration là một KHOẢNG THỜI GIAN, increment là PHẦN SẢN PHẨM sinh ra trong khoảng đó — cặp này bị hỏi rất nhiều. Sprint là tên gọi của iteration trong Scrum, còn iteration là từ chung dùng được cho mọi khung agile, nên đề không nói Scrum thì vẫn dùng được từ này."},{en:"iterative",alt:["iteratively"],vi:"cách tiếp cận làm nhiều lượt trên cùng một thứ, mỗi lượt lấy phản hồi rồi tinh chỉnh cho đúng hơn, thay vì cố làm đúng ngay từ lần đầu",trap:'Iterative nhắm vào "làm cho ĐÚNG THỨ khách cần" qua nhiều lượt tinh chỉnh; incremental nhắm vào "giao dần từng miếng dùng được". Khi đề nói yêu cầu còn mơ hồ và cần phản hồi để hiểu đúng thứ khách muốn, đó là lý lẽ cho iterative — dùng cả hai thì mới ra agile đầy đủ.'},{en:"spike",vi:"một lượt nghiên cứu ngắn có đóng hộp thời gian, làm riêng để trả lời một câu hỏi kỹ thuật hoặc giảm bất định trước khi cam kết làm thật",trap:'Trong PMP, spike là hoạt động NGHIÊN CỨU, không phải "đột biến số liệu" như nghĩa thông thường của từ này. Điểm sống của spike là timebox: hết hộp thời gian thì dừng và báo cái học được, dù chưa có câu trả lời trọn vẹn. Spike hợp khi bất định đến từ KỸ THUẬT; nếu bất định chỉ là các bên chưa cùng nhận định thì nói chuyện với nhau trước đã, dựng thử tốn hơn nhiều.'},{en:"servant leadership",alt:["servant leader","servant leaders","servant-leader","servant-leadership"],vi:"kiểu lãnh đạo đặt việc gỡ rào chắn và nâng năng lực cho nhóm lên trước quyền ra lệnh: hỏi nhóm đang tắc ở đâu rồi đi lo chỗ đó",trap:'Đây là một trong những đáp án "đúng theo PMI mindset" xuất hiện nhiều nhất, vì PMBOK 7 coi nhóm là nơi tạo ra kết quả còn người quản lý là người tạo điều kiện. Khi hai phương án nghe đều hợp lý, cái nào giúp nhóm tự làm được (kèm cặp, huấn luyện, tháo trở ngại) thường thắng cái nào PM nhảy vào làm thay, phân việc thay, hoặc leo lên cấp trên. Servant leadership không có nghĩa là buông lỏng hay dễ tính — vẫn phải giữ ranh giới vai và bảo vệ nhóm khỏi can thiệp từ ngoài.'},{en:"cross-functional",alt:["cross functional","cross-functionality"],vi:"đội có đủ mọi kỹ năng cần thiết để đi từ ý tưởng tới sản phẩm dùng được, không phải chờ chuyển việc sang phòng khác",trap:"Lý do PMI thiên về cross-functional: mỗi lần bàn giao giữa các phòng ban là một chỗ phải chờ và một chỗ rơi thông tin, nên phương án đưa đủ kỹ năng vào một đội thường thắng phương án lập thêm quy trình phối hợp giữa các phòng. Cross-functional nói về ĐỘI có đủ kỹ năng, không phải mỗi người phải làm được mọi việc."},{en:"predictive",vi:"cách tiếp cận lập kế hoạch chi tiết phạm vi, thời gian, chi phí ngay từ đầu rồi kiểm soát thay đổi so với baseline — dùng khi yêu cầu đã rõ và ổn định",trap:"Waterfall là MỘT DẠNG của predictive, không phải một thứ khác đứng ngang. Predictive cũng không có nghĩa là cấm thay đổi: thay đổi vẫn được, nhưng phải đi qua change control chứ không tự nhét vào. Đề mô tả yêu cầu rõ ràng, ràng buộc hợp đồng hoặc quy định chặt thì nghiêng predictive; mô tả yêu cầu còn biến động nhiều thì nghiêng adaptive."},{en:"adaptive",vi:"nhóm cách tiếp cận làm theo lượt ngắn và lấy phản hồi để chỉnh hướng thay vì chốt hết kế hoạch từ đầu — agile, iterative, incremental đều nằm trong nhóm này",trap:'Adaptive không phải "không lập kế hoạch", mà là lập kế hoạch nhiều lần ở mức chi tiết vừa đủ cho lượt tới (progressive elaboration). Chọn adaptive vì yêu cầu còn bất định và phản hồi sớm có giá trị, không phải vì nó hiện đại hơn: đề mô tả phạm vi đã chốt và cần dự báo chi phí chắc chắn thì adaptive là đáp án sai.'},{en:"hybrid",vi:"chọn cách tiếp cận theo từng phần công việc trong cùng một dự án: phần nào yêu cầu đã rõ thì làm predictive, phần nào còn bất định thì làm adaptive",trap:'Hybrid không phải "làm nửa nọ nửa kia" cho có cả hai, mà là quyết định có lý do cho từng khối việc. Phương án hybrid chỉ đúng khi đề cho thấy dự án có hai loại công việc khác nhau về mức bất định; dán vài sự kiện agile lên một dự án predictive không làm nó thành hybrid. Cũng đừng lẫn công cụ kỹ thuật với cách tiếp cận: thêm một công cụ tự động hóa không phải là một kỹ thuật hybrid.'},{en:"waterfall",vi:"lối làm tuần tự theo pha — phân tích xong mới thiết kế, thiết kế xong mới xây — mỗi pha là một cửa để đi tiếp",trap:"Waterfall là một dạng của predictive, nên đừng coi nó là loại thứ tư đứng ngang với predictive/adaptive/hybrid. PMI không coi waterfall là sai: khi yêu cầu ổn định và chi phí sửa về sau rất cao (xây dựng, thiết bị, việc phải tuân thủ quy định) thì đây là lựa chọn hợp lý. Điểm yếu duy nhất nhưng lớn là phản hồi của người dùng tới quá muộn để sửa rẻ."},{en:"tailoring",alt:["tailor","tailored"],vi:"chọn và điều chỉnh quy trình, phương pháp, mức tài liệu cho vừa với dự án cụ thể, thay vì áp nguyên một khuôn có sẵn",trap:'Đây là một nguyên tắc của PMBOK 7, nên phương án "áp đúng chuẩn công ty hoặc chuẩn ngành cho mọi dự án" thường là distractor, còn phương án điều chỉnh cho phù hợp đặc thù dự án thường thắng — nhất là khi đề nhấn dự án này khác thường lệ. Tailoring không phải cắt bỏ tùy ý cho đỡ việc: phần tổ chức và quy định bắt buộc vẫn phải giữ, và phần điều chỉnh phải nói được lý do.'},{en:"development approach",alt:["development approaches"],vi:"cách bạn sẽ tạo ra sản phẩm — predictive, adaptive, hay hybrid — chọn theo mức bất định của yêu cầu, loại sản phẩm, và ràng buộc của tổ chức",trap:"Đây là một quyết định phải lý giải được, không phải sở thích hay thói quen của đội: căn cứ chính là yêu cầu đã rõ tới đâu, một lần đổi hướng tốn bao nhiêu, và khách hàng có sẵn sàng tham gia liên tục hay không. Trong PMBOK 7 nó là một performance domain, đi kèm nhịp giao hàng (cadence) và vòng đời dự án, nên chọn approach là chọn luôn cả cách giao và cách đo tiến độ."}],v=[{en:"change request",alt:["change requests"],vi:"đề nghị chính thức để sửa thứ đã chốt baseline — phạm vi, lịch, chi phí hay tài liệu — thay vì sửa lặng lẽ",trap:"Đề nêu một đề xuất thay đổi rồi hỏi PM làm gì tiếp thì đáp án gần như luôn là phân tích tác động trước, chưa phải nộp change request và càng không phải tự làm luôn. Hai chỗ khác dễ sai: trong dự án agile yêu cầu mới đi vào product backlog cho product owner xếp ưu tiên chứ không cần change request; và một thay đổi đã được đề xuất thì là thay đổi, đừng ghi nó vào risk register."},{en:"change control board",alt:["CCB"],vi:"hội đồng có thẩm quyền duyệt hoặc từ chối change request, và là nơi duy nhất baseline được phép đổi",trap:'Khác steering committee: CCB quyết thay đổi trong phạm vi/lịch/chi phí của chính dự án, steering committee định hướng và quyết những chuyện lớn hơn bản thân dự án. Đề hỏi "trình cho ai" thì soi xem thay đổi đó nằm ở tầng nào. Bẫy thứ hai còn hay gặp hơn: CCB chỉ duyệt thứ đã được phân tích, nên phương án "forward to CCB" thường sai vì sai thứ tự chứ không phải sai người — đẩy một đề xuất thô lên hội đồng là bắt họ làm phần việc của bạn. CCB là cơ chế của dự án predictive; trong agile không có nó.'},{en:"integrated change control",vi:"quy trình xem xét mọi thay đổi trên toàn bộ dự án cùng lúc, để một thay đổi phạm vi không âm thầm phá lịch, chi phí và chất lượng",trap:'Chữ integrated là phần đáng nhớ: không duyệt thay đổi theo từng mảng riêng lẻ mà phải cân tác động chéo. Hai chỗ mất điểm: thay đổi có lợi cũng phải đi qua quy trình này chứ không được miễn; và PM không tự duyệt, PM chỉ chuẩn bị đủ dữ kiện cho người có thẩm quyền quyết. Quy trình chỉ có nghĩa khi đã có baseline — đề nói dự án chưa từng chốt phạm vi thì phương án "áp change control" là chữa sai bệnh.'},{en:"business case",vi:"tài liệu trả lời vì sao dự án đáng làm: lợi ích kỳ vọng, chi phí, và cơ sở biện minh cho khoản đầu tư",trap:'Bốn tài liệu hay bị lẫn, phân biệt bằng câu hỏi mà mỗi cái trả lời: business case là "vì sao làm", project charter là "được phép làm, ai cầm", project management plan là "làm thế nào", benefits management plan là "lợi ích được đo và theo dõi thế nào sau khi bàn giao". Business case có trước charter, và do sponsor hoặc bên tài trợ lập chứ không phải PM. Đề hỏi tài liệu nào cho biết mục tiêu và lợi ích chiến lược của dự án thì đó là business case.'},{en:"project charter",alt:["charter"],vi:"văn bản sponsor duyệt để khai sinh dự án và trao quyền cho PM, chốt mục tiêu, phạm vi mức cao và milestone mức cao",trap:'Charter trả lời "dự án được phép tồn tại và ai cầm nó", không trả lời "làm thế nào" — cái đó là project management plan. Bẫy quen thuộc: đề hỏi ngày cụ thể mà bạn chọn charter; charter chỉ có milestone ước chừng ở mức cao, ngày chắc chắn chỉ có sau khi lập kế hoạch xong. Khi đề đã nói charter được duyệt rồi thì mọi phương án kiểu "làm charter" hay "xin phê duyệt dự án" là thừa, và đó thường là chi tiết đề gài sẵn để bạn loại bớt.'},{en:"project management plan",vi:"tài liệu tổng nói dự án sẽ được thực thi, theo dõi và kiểm soát thế nào — gồm các baseline và các kế hoạch con của từng lĩnh vực",trap:'Đừng đánh đồng với "project plan" nói chung hay với lịch trình: lịch chỉ là một phần. Phân biệt với project document (risk register, issue log, stakeholder register, lessons learned register): document ghi tình hình đang diễn ra và cập nhật liên tục, còn plan đã được duyệt và chỉ đổi qua integrated change control. Mẹo phân đôi rất hay dùng trong đề: hỏi "xử lý ca cụ thể này thế nào" thì tra register, hỏi "chúng ta quản chuyện này theo quy trình nào" thì tra plan.'},{en:"benefits management plan",vi:"kế hoạch nói lợi ích của dự án sẽ được đo bằng gì, ai theo dõi, và theo dõi tới bao lâu sau khi bàn giao",trap:"Rất dễ lẫn với business case: business case nói lợi ích kỳ vọng để biện minh cho việc đầu tư, benefits management plan nói cơ chế đo và duy trì lợi ích đó sau khi sản phẩm đã ra. Dấu hiệu nhận dạng nhanh: trong bốn tài liệu khởi đầu, đây là cái duy nhất quan tâm tới quãng thời gian sau khi dự án đã đóng."},{en:"steering committee",vi:"nhóm lãnh đạo ở tầng trên dự án, lo định hướng và quyết những chuyện vượt thẩm quyền PM",trap:'Khác change control board: CCB duyệt thay đổi baseline, steering committee quyết chuyện lớn hơn bản thân dự án. Trong đề, "báo lên steering committee" hầu như luôn là phương án sai vì một trong hai lý do: leo thang quá tay cho việc thuộc thẩm quyền của PM hoặc product owner, hoặc leo thang khi tay chưa có phân tích nào — câu đầu tiên họ hỏi lại chính là câu bạn chưa trả lời. Chỉ chọn khi đề cho thấy quyết định thật sự vượt quyền bạn và bạn đã có dữ liệu.'},{en:"PMO",alt:["project management office"],vi:"bộ phận đặt chuẩn, cấp template và phương pháp, hỗ trợ các dự án trong tổ chức",trap:'PMO hỗ trợ và đặt chuẩn, không quản dự án thay bạn — phương án kiểu "nhờ PMO xác định ưu tiên" hay "để PMO phân bổ ngân sách" là giao đi phần việc thuộc trách nhiệm PM. Khi đề nói PMO đã có template thì đó là gợi ý bạn không phải dựng khung quy trình lại từ đầu, không phải gợi ý đi hỏi PMO.'},{en:"organizational process assets",vi:"những thứ tổ chức đã có mà dự án dùng lại được: template, quy trình, biểu mẫu, dữ liệu dự án cũ, lessons learned repository",trap:'Phân biệt với enterprise environmental factors: OPA là tài sản bạn dùng lại và tailor được, EEF là điều kiện bạn phải chịu và không đổi được (luật, văn hoá tổ chức, thị trường, hạ tầng có sẵn). Câu hỏi phân loại thì cứ hỏi một câu: dùng lại được, hay phải chịu. Lưu ý thêm: PMI coi OPA là đầu vào chuẩn, nhưng template của dự án khác vẫn phải tailor — đề hay dựng phương án "lấy template có sẵn" nghe rất hợp lý mà vẫn thua phương án hỏi người biết đặc thù dự án này.'},{en:"stakeholder register",vi:"danh sách các bên liên quan kèm lợi ích, mức ảnh hưởng và nhu cầu thông tin của từng người",trap:"Cặp cần thuộc: stakeholder register là ai và cần gì (dữ liệu về từng người), stakeholder engagement plan là chiến lược làm việc với họ (quy trình) — cùng logic với cặp risk register và risk management plan. Đề mô tả một bên liên quan bị bỏ sót ngay từ khâu nhận diện thì gốc rễ nằm ở register, không nằm ở kênh truyền thông. Đừng lẫn với communication log: log ghi lại những gì đã gửi, không cho biết ai đáng lẽ phải nhận."},{en:"RACI",vi:"bảng phân vai theo bốn mức Responsible (người làm), Accountable (người chịu trách nhiệm cuối), Consulted (được hỏi ý), Informed (được thông báo)",trap:"Điểm hay bị hỏi nhất: mỗi hàng chỉ được đúng MỘT chữ A — hai người cùng chịu trách nhiệm cuối nghĩa là không ai chịu. R thì có thể nhiều người, A thì không. Bẫy thứ hai: RACI phân vai cho con người, nó không phân rã phạm vi — đề hỏi về việc chia phạm vi thành các thành phần nhỏ hơn thì đáp án là WBS, và RACI thường làm sau khi đã biết có những work package nào."},{en:"subject matter expert",alt:["SME"],vi:"người có chuyên môn sâu một mảng, được kéo vào để cho ý kiến chuyên gia khi PM hoặc nhóm không đủ nền",trap:"Mẫu lặp đi lặp lại trong domain People: khi có SME mà nhóm đang thiếu năng lực, phương án dùng SME để nâng cả nhóm (workshop, đào tạo, chuyển giao kiến thức) thắng phương án để SME tự làm hộ hoặc chỉ trao đổi riêng với PM. Lý do: SME rời đi thì năng lực phải ở lại với nhóm, còn để kiến thức đọng vào một người là tự tạo key-person risk."},{en:"escalation",alt:["escalate","escalating"],vi:"chuyển một việc lên tầng có thẩm quyền cao hơn khi nó vượt quyền quyết của bạn",trap:"Trong PMP từ này có hai nghĩa và đề dùng cả hai. Một là hành vi quản trị: leo thang lên sponsor, steering committee hay PMO. Hai là một chiến lược ứng phó rủi ro chính thức: rủi ro nằm ngoài phạm vi hoặc ngoài thẩm quyền PM thì escalate cho chủ thể phù hợp, và sau khi escalate thì nhóm dự án không còn theo dõi rủi ro đó nữa — đây là chỗ khác accept, vì accept là vẫn giữ rủi ro trong dự án. Chỗ mất điểm nhiều nhất là thứ tự: escalate làm sau khi đã có phân tích và khi quyết định thật sự vượt quyền bạn, không phải phản xạ đầu tiên. Cũng đừng lẫn với việc ngồi lại cùng một bộ phận khác để gỡ vướng — đó là hợp tác giữa hai bên đều có lợi ích chính đáng, không phải mách cấp trên."},{en:"conflict resolution",vi:"cách PM xử lý xung đột trong nhóm hoặc giữa các bên, và trong PMP thì PM là người phải trực tiếp đứng ra làm việc đó",trap:"PMI liệt kê năm cách: collaborate/problem-solve, compromise/reconcile, smooth/accommodate, withdraw/avoid, force/direct. Thứ tự ưu tiên mặc định đặt collaborate lên đầu và force xuống cuối, nhưng cuối không đồng nghĩa với không bao giờ — đối thoại đã thử mà không cải thiện và dự án đang bị chặn thì force có thể là đáp án. Đề hay đặt sẵn các phương án né: hoãn quyết định (withdraw), bỏ phiếu, thuê trọng tài bên ngoài, đẩy lên cấp trên, hay giao cho trưởng bộ phận tự xử — điều phối xung đột là phần việc PM cầm, không chuyển đi được."},{en:"collaborate",vi:"một trong năm cách xử lý xung đột theo PMI: đưa các bên ngồi cùng nhau, đặt dữ liệu lên bàn, tìm phương án cả hai bên đều được — còn gọi là problem-solve",trap:"PMI coi đây là cách tốt nhất, nên trong câu hỏi về xung đột thì phương án đưa hai bên vào cùng một phòng thường thắng. Khác compromise: collaborate nhắm tới win-win, compromise là cả hai cùng nhượng nên cả hai đều mất một phần. Cẩn thận hai mẹo đặt đề ngược nhau: có phương án gắn chữ collaborative nhưng vế quyết định lại là né việc hoặc đẩy việc, và có phương án dùng chữ compromise nhưng bản chất là tổ chức một buổi ngồi cùng nhau bàn — bản chất đó vẫn là collaborate. Đọc vế động từ chính, đừng bắt từ khoá."},{en:"compromise",alt:["compromising"],vi:"một trong năm cách xử lý xung đột theo PMI: mỗi bên nhượng một phần để có phương án tạm chấp nhận được — còn gọi là reconcile",trap:'PMI xếp compromise dưới collaborate: compromise là lose-lose ở mức nhẹ, hai bên đều mất một phần và không ai được đúng thứ mình cần, còn collaborate nhắm tới win-win. Nếu trong bốn phương án có cái nào đưa các bên cùng giải quyết gốc vấn đề thì nó thắng phương án chia đôi thiệt hại. Lưu ý từ này trong đề đôi khi mang nghĩa thông thường ("compromising on functionality", "does not compromise security"), lúc đó nó là hy sinh hoặc làm hỏng chứ không phải cách xử lý xung đột — đọc bối cảnh trước khi gắn nhãn.'},{en:"Tuckman stages",re:"tuckman|(?<![A-Za-z])(?:storming|norming)(?![A-Za-z])",vi:"năm bậc một nhóm đi qua — forming (mới ráp, còn dè dặt), storming (xung đột lộ ra), norming (thống nhất cách làm việc), performing (chạy hiệu quả), adjourning (giải tán khi xong việc)",trap:"Phải chẩn đoán nhóm đang ở bậc nào trước khi chọn hành động. Nhóm mới ráp lại mà mỗi người thích làm một mình là còn ở forming, chưa vượt qua storming để tới norming; việc của PM là rút ngắn quãng đó, và cách rút ngắn không phải nói về hợp tác mà là tạo ra một lần hợp tác thật — workshop có một việc chung buộc phải cùng giải. Xung đột nổ ra không phải dấu hiệu nhóm tệ, đó là storming và là bậc bắt buộc phải qua. Cũng đừng nhầm adjourning với dự án thất bại: nó chỉ là giải tán sau khi xong việc."},{en:"Herzberg",vi:"thuyết hai yếu tố: hygiene factor chỉ chặn bất mãn, motivator mới tạo ra động lực",trap:"Đây là chỗ sai nhiều nhất vì trực giác bảo tăng lương thì có động lực. Theo Herzberg thì không: tiền, thưởng, nội quy, điều kiện làm việc, chính sách công ty đều là hygiene — thiếu thì người ta bất mãn, có thêm cũng không sinh ra động lực bền. Motivator là sự ghi nhận, ý nghĩa công việc, trách nhiệm, cơ hội phát triển. Đề hỏi làm gì để giữ động lực thì chọn phương án ghi nhận và làm việc có ý nghĩa, loại phương án tiền thưởng — nhất là phương án ra giá kiểu muốn được thưởng thì phải làm thêm giờ, vì ai từ chối lập tức bị dán nhãn kém nhiệt tình."},{en:"lessons learned",vi:"những gì học được từ dự án, ghi lại để chính dự án này sửa ngay và để dự án sau khỏi mắc lại",trap:"Phân biệt hai chỗ chứa: lessons learned register ghi trong lúc dự án đang chạy và cập nhật liên tục, còn lessons learned repository là kho của tổ chức (một organizational process asset) dùng cho các dự án sau — register được dồn vào repository khi đóng dự án. Bẫy thường gặp: đề mô tả một người giữ hết kiến thức rồi rời đi, đáp án là cơ chế làm thông tin thuộc về tổ chức (register, kho tài liệu dùng chung, PMIS) chứ không phải trông vào việc ai đó chủ động chia sẻ. Bẫy thứ hai: lessons learned của một dự án khác, nhà thầu khác, phạm vi khác nghe rất chuyên nghiệp nhưng không thay được việc phân tích tình huống đang ở trước mặt."}],o=Object.freeze([...p,...m,...s,...v].sort((n,i)=>n.en.localeCompare(i.en)));new Map(o.map(n=>[n.en.toLowerCase(),n]));const k=n=>u([n.q,...n.opts,...n.why,n.exp,n.arNote??""].join(`
`),o);export{o as G,u as f,k as t};
